//===- ctbrowser/lib/Core/unicode_lowercase.cpp - UTF-16 lowercasing ------===//
//
// unicode_lowercase_unit: the Unicode default lowercase mapping of one UTF-16
// code unit, from the range table in unicode_lowercase.inc (generated by
// tools/gen/unicode_lowercase.py).
//
//===----------------------------------------------------------------------===//

#include <ctbrowser/core/algorithms.hpp>

#include <algorithm>
#include <array>

namespace ctbrowser {
namespace {

/// A run of code units [first, last] whose lowercase is `unit + delta`, for
/// every `stride`-th unit from `first` (stride 2 covers alternating
/// upper/lower pairs).
struct lowercase_range {
    char16_t first;
    char16_t last;
    std::uint16_t stride;
    std::int32_t delta;
};

#include "unicode_lowercase.inc"

} // namespace

std::u16string unicode_lowercase_unit(char16_t unit) {
    // The only expanding default lowercase mapping for a single UTF-16 unit.
    if (unit == u'\u0130') { return u"i\u0307"; }
    const auto range = std::ranges::lower_bound(lowercase_ranges, unit, {}, &lowercase_range::last);
    if (range != lowercase_ranges.end() && unit >= range->first &&
        (unit - range->first) % range->stride == 0) {
        unit = static_cast<char16_t>(static_cast<std::int32_t>(unit) + range->delta);
    }
    return std::u16string(1, unit);
}

} // namespace ctbrowser
